import React from 'react';
import './App.css';

/**
 * ?  =====Import Components=====
 */
import Home from './Pages/Home';
import { BrowserRouter as Router } from 'react-router-dom';

function App() {
  return (
    <div>
      <Router>
        <Routes>
          <Route></Route>
        </Routes>
      </Router>
      <Home />
    </div>
  );
}

export default App;
